-- ============================================================
-- Claww: exercise form guides (V2 PHASE 8)
--
-- GENERATED from database/form_guides/*.json by
-- database/build_form_guides.mjs. Edit the JSON and re-run the script, not
-- this file. NEEDS REVIEW BY THE CO-FOUNDER: the text was drafted, not
-- sourced from a coach, and should be read for accuracy and tone.
--
-- Three numbered form steps and one common mistake per exercise, shown in the
-- player's form strip and the exercise guide sheet. Authored text only; it is
-- never generated at runtime. Run after schema.sql, seed_exercises.sql and
-- seed_exercise_metadata.sql. Safe to run any number of times.
-- ============================================================

UPDATE exercises AS e SET
  form_steps = v.form_steps,
  common_mistake = v.common_mistake
FROM (VALUES
  ('Running', ARRAY['Stand tall, eyes ahead, shoulders relaxed and arms bent about 90 degrees swinging forward and back.', 'Land with your foot close under your body and roll through quickly, with short, light steps.', 'Keep a steady breathing rhythm at a pace where you could still say a short sentence.']::text[], 'Overstriding, reaching the foot far in front, which brakes every step and hammers the knees.'),
  ('Jogging', ARRAY['Run tall with a slight forward lean from the ankles and relaxed hands.', 'Take short, quick steps landing under your hips, and let your arms swing gently.', 'Hold a pace that is easy enough to breathe through your nose or hold a conversation.']::text[], 'Starting too fast and then fading, instead of settling into an easy pace you can hold.'),
  ('Brisk Walking', ARRAY['Walk tall with your chin level and shoulders back and relaxed.', 'Swing your bent arms from the shoulders and take quick, comfortable strides.', 'Land on your heel and roll through to push off with your toes, aiming for a pace that raises your breathing.']::text[], 'Strolling with short steps and still arms, which leaves your heart rate barely raised.'),
  ('Power Walking', ARRAY['Stand tall and drive your elbows back, with arms bent about 90 degrees.', 'Take quick, purposeful steps that roll heel to toe, pushing off strongly with the back foot.', 'Keep the pace high enough that you are breathing hard but can still talk in short phrases.']::text[], 'Overreaching with the front foot and leaning back, which slows the stride and strains the shins.'),
  ('Sprint Intervals', ARRAY['Warm up with a few minutes of easy jogging and a couple of short build-ups first.', 'Sprint at close to full effort for the set time, driving your knees and arms hard.', 'Walk or jog easily to recover fully before the next sprint.']::text[], 'Sprinting cold or cutting the recovery short, which makes each rep slower and raises injury risk.'),
  ('Hill Sprints', ARRAY['Pick a steady incline and warm up with easy jogging and a couple of short build-ups.', 'Lean slightly into the hill and drive hard with your knees and arms for the whole effort.', 'Walk back down slowly to recover fully before the next sprint.']::text[], 'Looking down at your feet and bending at the waist instead of leaning from the ankles.'),
  ('Fartlek Running', ARRAY['Start with a few minutes of easy running to warm up.', 'Mix in bursts of faster running of different lengths, picking landmarks like lamp posts as your start and finish.', 'Recover with easy jogging until you feel ready, then pick the next burst.']::text[], 'Making every burst all-out, so the later ones fall apart and the session becomes a slog.'),
  ('Jump Rope', ARRAY['Hold the handles at hip height with your elbows close and turn the rope with your wrists.', 'Jump just high enough for the rope to pass, landing softly on the balls of your feet.', 'Keep a steady rhythm with your eyes forward and knees slightly bent.']::text[], 'Jumping too high and turning the rope with the whole arms, which tires you out quickly.'),
  ('High Knees', ARRAY['Stand tall with your feet hip-width apart and your arms bent at your sides.', 'Run in place, driving each knee up to hip height while pumping your opposite arm.', 'Stay on the balls of your feet with your chest up and core tight.']::text[], 'Leaning back and landing on the heels instead of staying tall on the balls of the feet.'),
  ('Butt Kicks', ARRAY['Stand tall with your feet hip-width apart and your arms bent at your sides.', 'Jog in place, flicking each heel up toward your glutes.', 'Keep your knees pointing down and your hips level as you stay light on your feet.']::text[], 'Letting the knees swing forward so the move turns into a bouncy jog with no hamstring work.'),
  ('Jumping Jacks', ARRAY['Start standing with your feet together and your arms by your sides.', 'Jump your feet out wide while swinging your arms overhead.', 'Jump back to the start and repeat at a steady rhythm, landing softly.']::text[], 'Landing stiff-legged on the heels, which jars the knees and hips.'),
  ('Skater Jumps', ARRAY['Stand on one leg with a slight bend in the knee and your torso tilted forward.', 'Leap sideways to the other leg, swinging your arms across your body for balance.', 'Land softly on the new leg, absorb it with a bent knee and immediately leap back.']::text[], 'Landing on a straight leg or letting the knee cave in, which jolts the joint.'),
  ('Broad Jumps', ARRAY['Stand with your feet shoulder-width apart and swing your arms back as you sit your hips back.', 'Swing your arms forward and explode up and forward as far as you can.', 'Land softly with bent knees, hips back, and reset before the next jump.']::text[], 'Landing with straight legs or the chest collapsed, which sends the impact into the knees and back.'),
  ('Tuck Jumps', ARRAY['Stand with your feet hip-width apart and your knees slightly bent.', 'Jump straight up and pull both knees toward your chest at the top.', 'Land softly on the balls of your feet with bent knees and reset before the next one.']::text[], 'Rushing the next rep before the landing is stable, which causes sloppy, stiff landings.'),
  ('Shadow Boxing', ARRAY['Stand with your feet shoulder-width apart in a light stance, knees soft and hands up by your chin.', 'Throw jabs, crosses and hooks with your hips and shoulders turning into each punch.', 'Stay on the balls of your feet, moving around and breathing out with each punch.']::text[], 'Throwing arm-only punches and locking the elbows hard at full extension.'),
  ('Burpee Cardio Circuit', ARRAY['Do a burpee: squat, kick back to a plank, lower your chest, then jump your feet back in.', 'Explode into a jump with your arms overhead and land softly.', 'Move straight into the next exercise in the circuit and keep a steady pace.']::text[], 'Letting the hips sag in the plank when tired, which puts the load on the lower back.'),
  ('Stair Sprints', ARRAY['Warm up first, then start at the bottom of a flight of stairs, leaning slightly forward.', 'Drive up two stairs at a time or one quickly, pumping your arms and pushing through the whole foot.', 'Walk back down carefully, one step at a time, and recover before the next climb.']::text[], 'Landing on your toes with your heels hanging off the step, which strains the calves and Achilles.'),
  ('Walking Lunges Cardio', ARRAY['Stand tall with your hands on your hips or arms swinging, feet hip-width apart.', 'Step forward into a lunge until both knees are about 90 degrees, then push off the front foot into the next step.', 'Keep moving at a steady pace with your chest up.']::text[], 'Taking short steps and letting the front knee drift far over the toes.'),
  ('Sprint Shuttles', ARRAY['Set two markers about 10 to 20 metres apart and warm up first.', 'Sprint to the far marker, plant one foot, touch the line and drive back.', 'Keep your steps short as you turn and rest between sets.']::text[], 'Turning on a straight, locked leg instead of bending the knee and pushing off the outside foot.'),
  ('Agility Ladder Drills', ARRAY['Lay a ladder flat and stand at one end on the balls of your feet.', 'Step quickly in and out of each square in the pattern, keeping your steps short and light.', 'Look ahead, not down, and keep your arms pumping.']::text[], 'Staring at your feet, which slows your rhythm and rounds your back.'),
  ('Lateral Bounds', ARRAY['Stand on one leg with your knee slightly bent and your torso tilted forward.', 'Push off sideways to the other leg, covering as much distance as you can control.', 'Land softly on the new leg, hold for a beat and bound back.']::text[], 'Rushing the landing, so the knee wobbles instead of absorbing the impact.'),
  ('Stationary Bike', ARRAY['Adjust the seat so your knee has a slight bend at the bottom of the pedal stroke.', 'Sit tall with a relaxed grip, and pedal in smooth circles at a steady cadence.', 'Add or reduce resistance to hold the effort you want.']::text[], 'A seat set too low, which puts stress on the knees and wastes power.'),
  ('Treadmill Walk', ARRAY['Start at a slow speed, holding the rails only to step on, then let go.', 'Walk tall with your shoulders relaxed, arms swinging naturally and eyes ahead.', 'Increase the speed or incline until your breathing is a bit heavier, then hold it.']::text[], 'Holding the handrails the whole time, which cuts the effort and throws off your posture.'),
  ('Treadmill Jog', ARRAY['Warm up with a brisk walk, then raise the speed until you are jogging comfortably.', 'Run tall in the middle of the belt with your arms swinging and steps landing under your hips.', 'Set a pace you can hold, adding a 1 percent incline if you want it closer to road running.']::text[], 'Running at the very front of the belt and reaching with the feet.'),
  ('Home Elliptical', ARRAY['Stand upright with your feet flat on the pedals and your hands lightly on the handles.', 'Push and pull in a smooth, controlled stride, keeping your weight over your hips.', 'Pick a resistance that keeps you working, and reverse direction now and then.']::text[], 'Leaning heavily on the handles, which removes most of the workload from your legs.'),
  ('Box Jump', ARRAY['Stand in front of a sturdy box with your feet shoulder-width apart.', 'Swing your arms back, sit your hips back, then jump up and land softly on the box with your whole foot.', 'Stand up tall and step down, rather than jumping down, then reset.']::text[], 'Choosing a box too high and landing in a deep squat, or jumping back down hard onto the knees.'),
  ('Battle Ropes', ARRAY['Stand with your feet shoulder-width apart, knees soft, and hold one rope end in each hand.', 'Make fast, alternating waves with your arms, driving from the shoulders and keeping your core tight.', 'Work in short bursts and breathe steadily.']::text[], 'Standing straight-legged and using only the wrists, which makes the waves small and strains the back.'),
  ('Step Aerobics', ARRAY['Stand facing a low step with your chest up and your abs braced.', 'Step up with one foot, bring the other up, and step down in a smooth, repeating pattern.', 'Land with your whole foot on the platform and keep your steps light.']::text[], 'Stepping so far back off the platform that you pull yourself off balance.'),
  ('Dance Cardio', ARRAY['Find a song or class with a steady beat and start with a gentle warm-up.', 'Move your whole body to the beat, keeping your knees soft and arms active.', 'Keep going without stopping, and scale the moves down if you are out of breath.']::text[], 'Standing stiffly and doing small movements, which keeps the effort too low.'),
  ('Kickboxing Cardio', ARRAY['Stand in a light stance with your hands up and your knees slightly bent.', 'Combine punches and kicks, turning your hips and shoulders into each strike.', 'Stay light on your feet between strikes and keep your guard up.']::text[], 'Kicking by locking the knee hard at full extension instead of snapping the leg back.'),
  ('Spin Bike Intervals', ARRAY['Set the saddle so your knee has a slight bend at the bottom, and warm up spinning easily.', 'Add resistance and pedal hard for the work interval, staying smooth and keeping your upper body still.', 'Drop the resistance and spin easily to recover before the next interval.']::text[], 'Gripping the handlebars tightly and bouncing on the saddle during the hard efforts.'),
  ('Home Cardio Circuit', ARRAY['Pick 4 to 6 bodyweight moves like squats, jacks, high knees and mountain climbers.', 'Do each for a set time or reps with good form and move on with little rest.', 'Repeat the circuit for the rounds you planned, resting a minute between rounds.']::text[], 'Rushing the first round so hard that form falls apart in the later ones.'),
  ('Cycling', ARRAY['Set your saddle so your knee has a slight bend at the bottom of the stroke.', 'Keep your back relaxed, hands light on the bars, and pedal in smooth circles.', 'Change gears to hold a steady cadence and effort.']::text[], 'Grinding in a hard gear at a low cadence, which strains the knees.'),
  ('Rowing Machine', ARRAY['Strap in, grab the handle with straight arms, and sit tall with your shins vertical.', 'Drive with your legs first, then lean back slightly and pull the handle to your lower ribs.', 'Reverse the order to return: arms out, torso forward, then bend the knees.']::text[], 'Pulling with the arms first and hunching, which loses most of the leg power.'),
  ('Stair Climber', ARRAY['Stand upright with your hands lightly on the rails, feet fully on the steps.', 'Climb at a steady pace, pushing through your whole foot with each step.', 'Keep your chest up and let the rails guide balance, not carry your weight.']::text[], 'Leaning on the rails and hunching forward, which cuts the work and strains the back.'),
  ('Elliptical Machine', ARRAY['Stand tall with your feet flat on the pedals and your hands on the moving handles.', 'Push and pull smoothly through the stride, driving through your heels.', 'Choose a resistance that keeps you working, and switch direction now and then.']::text[], 'Letting the knees collapse inward or hunching over the console.'),
  ('Treadmill Sprints', ARRAY['Warm up with easy running, then stand on the side rails while you set the sprint speed.', 'Step onto the belt and run hard for the interval, keeping your steps quick and landing under your hips.', 'Step back onto the side rails or slow to a walk to recover fully.']::text[], 'Stepping on at sprint speed from a standstill, which is easy to trip on.'),
  ('Swimming Laps', ARRAY['Push off the wall in a streamlined position, arms extended, face down.', 'Alternate your arms in smooth strokes, rotating your body, and kick from the hips.', 'Turn your head to breathe to the side every few strokes, keeping a steady rhythm.']::text[], 'Lifting the head to breathe, which sinks the hips and makes you work harder.'),
  ('Sled Push', ARRAY['Place your hands on the sled''s uprights with straight arms and a flat back, leaning forward.', 'Drive hard with your legs in short, powerful steps, pushing the sled ahead.', 'Keep your hips low and your core braced the whole distance.']::text[], 'Standing too upright with the hips high, which wastes force into the ground.'),
  ('Assault Bike', ARRAY['Adjust the seat so your knee has a slight bend, and sit tall.', 'Push and pull the handles with your arms while pedaling hard, in sync with your legs.', 'Pace the effort so you can keep going, with a steady rhythm of breathing.']::text[], 'Sprinting out of the gate and fading, instead of building to a hard but even effort.'),
  ('Ski Erg', ARRAY['Stand tall facing the machine, hands on the handles overhead.', 'Pull the handles down toward your thighs, hinging at the hips and bending your knees.', 'Return to standing as the handles rise, keeping the movement smooth.']::text[], 'Pulling with the arms alone, which tires them fast, instead of using the hips and core.'),
  ('Versaclimber', ARRAY['Step onto the pedals and take hold of the handles, standing tall.', 'Move opposite arm and leg together in a smooth climbing rhythm.', 'Keep your core tight, and use the full length of the reach.']::text[], 'Taking short, choppy strokes, which lowers the workload and tires the shoulders.'),
  ('Hip Flexor Stretch', ARRAY['Kneel on one knee with the other foot forward, and tuck your tailbone under.', 'Gently shift your hips forward until you feel a stretch at the front of the back-leg hip.', 'Hold while breathing slowly, then switch sides.']::text[], 'Arching the lower back instead of tucking the pelvis, which moves the stretch out of the hip.'),
  ('Cat-Cow Stretch', ARRAY['On hands and knees with your hands under your shoulders and knees under your hips.', 'Inhale and drop your belly while lifting your chest and tailbone, as in the cow.', 'Exhale and round your spine up toward the ceiling, tucking your chin, as in the cat.']::text[], 'Rushing through the movement instead of moving one vertebra at a time with each breath.'),
  ('World''s Greatest Stretch', ARRAY['Step into a deep lunge and place both hands inside your front foot.', 'Rotate your torso toward the front knee and reach that arm up to the ceiling.', 'Return your hand to the floor, straighten the front leg, then switch sides.']::text[], 'Letting the back knee drop and the chest collapse, which loses the hip and spine opening.'),
  ('Ankle Mobility Drill', ARRAY['Stand facing a wall with one foot a few inches away, toes pointing forward.', 'Drive your knee forward over your toes toward the wall while keeping your heel on the floor.', 'Return, then move your foot farther back as the range improves.']::text[], 'Letting the heel lift off the ground, which hides the ankle tightness you are trying to fix.'),
  ('Hamstring Stretch', ARRAY['Sit or stand and extend one leg in front with the heel down and the toes up.', 'Hinge forward from your hips with a flat back until you feel a stretch along the back of the thigh.', 'Hold while breathing slowly, then switch legs.']::text[], 'Rounding the back to reach the toes, which stretches the spine rather than the hamstring.'),
  ('Quad Stretch', ARRAY['Stand tall, holding a wall for balance, and bend one knee to bring your heel toward your glutes.', 'Hold your ankle and keep your knees close together, pushing your hip slightly forward.', 'Hold while breathing slowly, then switch legs.']::text[], 'Letting the knee drift forward or the lower back arch, which loses the stretch in the thigh.'),
  ('Calf Stretch', ARRAY['Stand facing a wall with your hands on it, one foot back with the heel on the floor.', 'Keep the back leg straight and lean forward until you feel the stretch in the calf.', 'Hold while breathing slowly, then switch legs.']::text[], 'Letting the back heel lift or the foot turn out, which takes the stretch off the calf.'),
  ('Shoulder Circles', ARRAY['Stand tall with your arms relaxed by your sides.', 'Roll your shoulders up, back and down in slow, large circles.', 'Reverse the direction after a few reps.']::text[], 'Making small, quick circles, which only wiggle the shoulders instead of using the full range.'),
  ('Arm Circles', ARRAY['Stand tall with your arms out to the sides at shoulder height.', 'Draw small circles with your hands, gradually making them larger.', 'Reverse the direction after a set number of circles.']::text[], 'Shrugging the shoulders toward the ears while the arms circle.'),
  ('Neck Rolls', ARRAY['Sit or stand tall with your shoulders relaxed.', 'Slowly drop your chin to your chest, then roll your ear toward one shoulder.', 'Continue in a gentle half circle, then repeat on the other side.']::text[], 'Rolling the head backward in a full circle, which compresses the back of the neck.'),
  ('Thoracic Spine Rotation', ARRAY['On hands and knees, place one hand behind your head.', 'Rotate that elbow down toward the opposite arm, then open it up toward the ceiling.', 'Follow the elbow with your eyes and repeat, then switch sides.']::text[], 'Twisting from the lower back instead of keeping the hips still and rotating through the upper back.'),
  ('Hip Circles', ARRAY['Stand on one leg, holding a wall for balance, and lift the other knee to hip height.', 'Draw slow, large circles with the knee, rotating at the hip.', 'Reverse the direction, then switch legs.']::text[], 'Leaning the whole body to swing the leg instead of moving only from the hip.'),
  ('Leg Swings', ARRAY['Stand next to a wall for balance and swing one leg forward and back in a controlled motion.', 'Keep your torso tall, gradually swinging a little higher each time.', 'Switch to side-to-side swings across your body, then change legs.']::text[], 'Swinging with force and arching the back instead of building range gradually.'),
  ('Walking Knee Hugs', ARRAY['Stand tall and step forward, pulling one knee up to your chest with both hands.', 'Squeeze for a second while you rise slightly onto the toes of the other foot.', 'Release, step forward and repeat on the other leg.']::text[], 'Rounding the back to bring the chest to the knee instead of lifting the knee up.'),
  ('Walking Quad Stretch', ARRAY['Stand tall and bend one knee to hold your ankle behind you, keeping your knees together.', 'Push your hip forward slightly and hold for a second.', 'Release, step forward and repeat on the other leg.']::text[], 'Leaning forward or letting the knee flare out to the side, which loses the stretch.'),
  ('Inchworm', ARRAY['Stand tall, then bend forward and place your hands on the floor in front of your feet.', 'Walk your hands out to a plank, keeping your legs as straight as you can.', 'Walk your feet toward your hands in small steps, then stand up.']::text[], 'Bending the knees a lot and rushing, which skips the hamstring stretch.'),
  ('Scorpion Stretch', ARRAY['Lie face down with your arms out to the sides.', 'Lift one leg and swing it across your body toward the opposite hand, rotating your hips.', 'Return, then repeat on the other side, keeping your shoulders on the floor.']::text[], 'Letting the shoulders lift off the floor as the leg crosses over.'),
  ('Figure-Four Stretch', ARRAY['Lie on your back with your knees bent and cross one ankle over the opposite knee.', 'Thread your hands behind the bottom thigh and pull it toward your chest.', 'Hold while keeping your head and shoulders relaxed, then switch sides.']::text[], 'Letting the crossed knee fall in or lifting the head off the floor to pull harder.'),
  ('Butterfly Stretch', ARRAY['Sit tall with the soles of your feet together and your knees dropped out to the sides.', 'Hold your feet and lean forward from your hips with a flat back.', 'Hold while breathing slowly and let the knees relax toward the floor.']::text[], 'Pressing the knees down with your hands, which strains the inner knee.'),
  ('Seated Forward Fold', ARRAY['Sit with your legs straight in front of you and your toes pointing up.', 'Hinge forward from your hips and reach toward your feet with a long spine.', 'Hold where you feel a stretch along the back of your legs, breathing slowly.']::text[], 'Rounding the upper back to reach farther, which shifts the stretch away from the hamstrings.'),
  ('Standing Side Bend', ARRAY['Stand tall with your feet hip-width apart and one arm reaching overhead.', 'Bend sideways from your waist, keeping your hips still.', 'Return to center and repeat on the other side.']::text[], 'Leaning forward or twisting as you bend, which loses the stretch along the side.'),
  ('Wrist Mobility Drill', ARRAY['On hands and knees with your fingers pointing forward, shift your weight gently back and forth.', 'Turn your hands so the fingers point sideways, then back, shifting gently each time.', 'Move within a comfortable range and stop if anything pinches.']::text[], 'Forcing weight onto the wrists too fast instead of easing in gradually.'),
  ('90/90 Hip Stretch', ARRAY['Sit on the floor with your front leg bent 90 degrees in front and your back leg bent 90 degrees to the side.', 'Sit tall, then lean your chest over the front shin until you feel a stretch in the outer hip.', 'Hold, then rotate to switch sides.']::text[], 'Leaning back on your hands to get comfortable, which removes the stretch.'),
  ('Deep Squat Hold', ARRAY['Stand with your feet slightly wider than your shoulders and toes turned out.', 'Sit down as low as you can with your heels down and chest up.', 'Press your elbows against your knees and hold, breathing slowly.']::text[], 'Letting the heels lift or the back round, which means you are past your current range.'),
  ('Spiderman Lunge', ARRAY['Start in a high plank, then step one foot outside your hand.', 'Sink your hips toward the floor and press your knee out with your elbow.', 'Return to plank and switch sides.']::text[], 'Letting the back hip sag, which loses the plank position.'),
  ('Cossack Squat', ARRAY['Stand with your feet wide and your toes turned out slightly.', 'Shift your weight to one side and sit down into that leg while the other leg stays straight.', 'Push back up through the heel, shift across to the other side and repeat.']::text[], 'Letting the heel of the working leg lift as you sit, which strains the knee.'),
  ('Windmill Stretch', ARRAY['Stand with your feet wide, one arm reaching overhead and the other hanging.', 'Hinge to the side, sliding the lower hand down your leg while watching the upper hand.', 'Return to standing and repeat, then switch sides.']::text[], 'Bending forward at the waist instead of hinging from the hip.'),
  ('Lat Stretch', ARRAY['Hold a stable support at about hip height and sit your hips back.', 'Drop your chest between your arms until you feel a stretch down the side of your back.', 'Hold, breathing into the stretch, then step out of it slowly.']::text[], 'Arching the lower back instead of keeping the spine long.'),
  ('Chest Opener Stretch', ARRAY['Stand tall and clasp your hands behind your back.', 'Straighten your arms and lift them gently away from your body as you open your chest.', 'Hold while breathing slowly and keeping your ribs down.']::text[], 'Pushing the ribs forward and arching the lower back to lift the arms higher.'),
  ('Groin Stretch', ARRAY['Sit with your legs wide apart and your toes pointing up.', 'Hinge forward from your hips with a long spine until you feel the stretch along the inner thighs.', 'Hold while breathing slowly.']::text[], 'Rounding the back and dropping the chin to the chest instead of hinging at the hips.'),
  ('Piriformis Stretch', ARRAY['Sit on the floor with one leg bent in front and the other crossed over it.', 'Hug the crossed knee toward your opposite shoulder with a long spine.', 'Hold while breathing slowly, then switch sides.']::text[], 'Twisting the spine to pull harder instead of keeping the hips square.'),
  ('IT Band Stretch', ARRAY['Stand with one leg crossed behind the other and reach the same-side arm overhead.', 'Lean away from the back leg, pushing that hip out to the side.', 'Hold while breathing slowly, then switch sides.']::text[], 'Leaning forward instead of straight to the side, which skips the outer hip and thigh.'),
  ('Foam Rolling', ARRAY['Place the foam roller under the muscle you want to release, supporting your weight with your hands.', 'Roll slowly over the muscle, pausing for a few seconds on tender spots.', 'Keep breathing and avoid rolling directly over joints or bones.']::text[], 'Rolling quickly back and forth instead of working slowly and pausing on tight spots.'),
  ('Resistance Band Shoulder Mobility', ARRAY['Hold a light band in front of you with both hands, wider than your shoulders.', 'Raise your arms overhead and then back behind you as far as is comfortable, keeping your arms straight.', 'Reverse to the start and move the hands closer together as the range improves.']::text[], 'Arching the lower back to get the band behind you instead of widening the grip.'),
  ('Yoga Strap Hamstring Stretch', ARRAY['Lie on your back and loop a strap around the ball of one foot.', 'Raise that leg toward the ceiling, keeping it as straight as is comfortable.', 'Hold with a gentle pull on the strap while breathing slowly, then switch legs.']::text[], 'Letting the lower back lift off the floor or the other knee bend.'),
  ('Foam Roller Thoracic Extension', ARRAY['Lie with the foam roller across your upper back and your hands behind your head.', 'Lower your upper back back over the roller, gently opening the chest.', 'Move the roller up or down a few inches and repeat.']::text[], 'Letting the ribs flare and the lower back arch instead of keeping the core lightly braced.'),
  ('Massage Ball Foot Rolling', ARRAY['Stand or sit with a massage ball under your foot.', 'Roll slowly from the heel to the ball of the foot, pausing on tender spots.', 'Apply moderate pressure and breathe, then switch feet.']::text[], 'Pressing so hard that you tense up, which defeats the release.'),
  ('Band-Assisted Hip Opener', ARRAY['Loop a band around a sturdy anchor and the top of your thigh, then step away to tension it.', 'Get into a lunge or kneeling position facing away from the anchor.', 'Let the band pull your hip back and sit into the stretch, breathing slowly.']::text[], 'Letting the band pull the hip forward instead of staying tall and tucking the pelvis.'),
  ('Foam Roller IT Band Release', ARRAY['Lie on your side with the foam roller under the outer thigh.', 'Roll slowly from just above the knee to the hip, supporting yourself with your arms.', 'Pause on tender spots, breathing steadily, then switch legs.']::text[], 'Rolling directly over the outside of the knee, which is a bony joint.'),
  ('Lacrosse Ball Glute Release', ARRAY['Sit on the floor with a lacrosse ball under one glute.', 'Cross that ankle over the opposite knee and lean into the ball.', 'Roll slowly over tender spots, breathing steadily, then switch sides.']::text[], 'Rolling the ball onto the lower back or the tailbone instead of the glute muscle.'),
  ('Assisted Stretch Machine', ARRAY['Set the machine for the stretch you want and adjust the pad to fit your body.', 'Move slowly into the stretch until you feel a gentle pull, not pain.', 'Hold while breathing slowly and release before you switch.']::text[], 'Forcing the range with the machine''s help beyond what the muscle is ready for.'),
  ('Pool Walking Mobility', ARRAY['Wade into waist-deep water and walk forward with an upright posture.', 'Add side steps, high knees and leg swings, moving with slow, wide motions.', 'Let the water support you and keep the movements smooth.']::text[], 'Hunching over or rushing the movements, which wastes the chance to move through full range.'),
  ('Push-Up', ARRAY['Hands just wider than your shoulders, body in one straight line from head to heels, core and glutes tight.', 'Lower your chest toward the floor with elbows about 45 degrees from your body, not flared out.', 'Press the floor away until your arms are straight, keeping your hips level the whole way.']::text[], 'Letting the hips sag or pike up, so the chest and core stop doing the work.'),
  ('Incline Push-Up', ARRAY['Hands on a bench or sturdy surface, a little wider than your shoulders, body in a straight line.', 'Lower your chest to the edge with elbows about 45 degrees from your body.', 'Press back up until your arms are straight without letting the hips drop.']::text[], 'Setting the hands too high and cutting the range short, so the chest never gets a full stretch.'),
  ('Decline Push-Up', ARRAY['Feet on a bench, hands on the floor just wider than your shoulders, body in a straight line.', 'Lower your chest toward the floor with elbows about 45 degrees from your body.', 'Press up and slightly back toward your feet until your arms lock out, keeping your core tight.']::text[], 'Dropping the head forward and piking the hips, which turns the move into a shoulder press.'),
  ('Diamond Push-Up', ARRAY['Hands under your chest with thumbs and index fingers touching to make a diamond, body in a straight line.', 'Lower your chest toward your hands while keeping your elbows close to your ribs.', 'Press up until your arms are straight, squeezing your triceps at the top.']::text[], 'Letting the elbows flare wide, which takes the work off the triceps and strains the wrists.'),
  ('Pike Push-Up', ARRAY['From a downward-dog shape with hips high, hands shoulder-width apart and legs nearly straight.', 'Bend your elbows and lower the top of your head toward the floor between your hands.', 'Press back up through your shoulders to the starting shape.']::text[], 'Walking the feet in so far that the move becomes a regular push-up with no shoulder load.'),
  ('Bodyweight Squat', ARRAY['Feet shoulder-width apart, toes turned slightly out, chest tall.', 'Sit your hips back and down until your thighs are at least parallel, knees tracking over your toes.', 'Drive through your whole foot to stand up, squeezing your glutes at the top.']::text[], 'Letting the knees cave inward or the heels lift as you come out of the bottom.'),
  ('Jump Squat', ARRAY['Start in a squat stance, chest tall, arms ready to swing.', 'Sit back into a quarter to half squat, then explode straight up off the floor.', 'Land softly on the middle of your feet, bend your knees to absorb it and go straight into the next rep.']::text[], 'Landing stiff-legged or with the knees caving in, which sends the impact into the joints.'),
  ('Wall Sit', ARRAY['Lean your back flat against a wall and walk your feet out until your knees are over your ankles.', 'Slide down until your thighs are parallel to the floor, with your lower back and shoulders against the wall.', 'Hold the position, breathing steadily, with your weight through your heels.']::text[], 'Resting your hands on your thighs, which takes load off the legs, or sitting too high to feel it.'),
  ('Bodyweight Lunge', ARRAY['Stand tall with your feet hip-width apart and your hands on your hips.', 'Step forward and lower until both knees are bent about 90 degrees, with your front knee over your ankle.', 'Push through the front foot to return to standing, then switch legs.']::text[], 'Taking too short a step so the front knee travels far past the toes and the heel lifts.'),
  ('Reverse Lunge', ARRAY['Stand tall with your feet hip-width apart and your chest up.', 'Step one foot back and lower until both knees are bent about 90 degrees, front shin close to vertical.', 'Push through the front heel to stand up, then switch legs.']::text[], 'Leaning the torso forward and shifting weight onto the back foot instead of the front leg.'),
  ('Bulgarian Split Squat', ARRAY['Stand about a step and a half in front of a bench and rest the top of one back foot on it.', 'Lower straight down until your front thigh is parallel to the floor, torso upright, front heel planted.', 'Drive through the front foot to stand, then finish all reps before switching legs.']::text[], 'Standing too close to the bench so the front knee shoves forward and the back foot does the work.'),
  ('Step-Up', ARRAY['Stand facing a sturdy box or bench, with one whole foot on top.', 'Press through that foot to stand up fully, without pushing off the floor foot.', 'Lower back down slowly under control, then repeat before switching legs.']::text[], 'Using the trailing leg to spring up, so the working leg does only part of the lift.'),
  ('Calf Raise', ARRAY['Stand tall with the balls of your feet on the floor or a step, hands on a wall for balance if needed.', 'Rise as high as you can onto your toes and pause for a second at the top.', 'Lower slowly until your heels are at or just below the step, then repeat.']::text[], 'Bouncing through the reps with a short range instead of pausing at the top and bottom.'),
  ('Pull-Up', ARRAY['Hang from the bar with an overhand grip just wider than your shoulders, shoulders pulled down away from your ears.', 'Pull your chest toward the bar by driving your elbows down and back.', 'Lower under control until your arms are fully straight before the next rep.']::text[], 'Swinging or kipping and cutting the bottom short, so the back never gets the full range.'),
  ('Chin-Up', ARRAY['Hang from the bar with an underhand grip about shoulder-width apart, shoulders set down.', 'Pull until your chin clears the bar, leading with your chest and keeping your elbows close.', 'Lower slowly to a full hang before the next rep.']::text[], 'Craning the neck to get the chin over the bar instead of pulling the chest up.'),
  ('Inverted Row', ARRAY['Lie under a sturdy bar or table, grip it just wider than your shoulders and hold your body in a straight line.', 'Pull your chest to the bar by squeezing your shoulder blades together.', 'Lower under control until your arms are straight, keeping your hips up.']::text[], 'Letting the hips sag, which shortens the pull and hides how weak the back is.'),
  ('Superman', ARRAY['Lie face down with your arms extended in front and your legs straight.', 'Lift your arms, chest and legs a few inches off the floor together, looking at the floor.', 'Hold for a second, squeezing your glutes and upper back, then lower with control.']::text[], 'Cranking the neck upward to look ahead instead of keeping it in line with your spine.'),
  ('Bodyweight Dip', ARRAY['Support yourself on parallel bars with straight arms, shoulders down and chest slightly forward.', 'Lower until your upper arms are about parallel to the floor, elbows tracking back.', 'Press up until your arms are straight without shrugging your shoulders.']::text[], 'Dropping far below parallel with the shoulders rolled forward, which strains the front of the shoulder.'),
  ('Bench Dip', ARRAY['Sit on the edge of a bench, place your hands beside your hips, and slide your hips off with legs out in front.', 'Bend your elbows straight back and lower until your upper arms are about parallel to the floor.', 'Press up through your palms until your arms are straight.']::text[], 'Sliding too far from the bench and dropping too deep, which overloads the front of the shoulders.'),
  ('Plank', ARRAY['Forearms on the floor with elbows under your shoulders, legs straight, body in one line from head to heels.', 'Brace your core and squeeze your glutes as if bracing for a punch.', 'Hold while breathing steadily, keeping your hips level.']::text[], 'Letting the lower back sag or the hips rise, which takes the work off the abs.'),
  ('Side Plank', ARRAY['Lie on your side with your forearm under your shoulder and your legs stacked or staggered.', 'Lift your hips so your body forms one straight line from head to feet.', 'Hold, keeping your hips high and your top shoulder stacked over the bottom one.']::text[], 'Letting the hips drop toward the floor or rolling forward, so the obliques stop working.'),
  ('Bird Dog', ARRAY['On hands and knees with your hands under your shoulders and knees under your hips, back flat.', 'Reach one arm forward and the opposite leg back until both are in line with your torso.', 'Pause for a second without rotating your hips, then return and switch sides.']::text[], 'Arching the lower back and letting the hips twist as the leg lifts.'),
  ('Glute Bridge', ARRAY['Lie on your back with your knees bent, feet flat and hip-width apart, arms by your sides.', 'Drive through your heels to lift your hips until your body forms a line from shoulders to knees.', 'Squeeze your glutes at the top for a second, then lower with control.']::text[], 'Pushing the hips so high that the lower back arches, which shifts the work off the glutes.'),
  ('Single-Leg Glute Bridge', ARRAY['Lie on your back with one foot flat on the floor and the other leg extended straight up or out.', 'Drive through the planted heel to lift your hips until they are level.', 'Pause at the top, then lower slowly without letting the hips twist.']::text[], 'Dropping one hip as you lift, which turns it into a lower-back arch.'),
  ('Mountain Climbers', ARRAY['Start in a high plank with your hands under your shoulders and your body in a straight line.', 'Drive one knee toward your chest, then switch legs quickly as if running in place.', 'Keep your hips level and your core tight throughout.']::text[], 'Bouncing the hips high into the air, which turns the move into a rushed squat thrust.'),
  ('Burpee', ARRAY['From standing, squat and place your hands on the floor, then jump or step your feet back to a plank.', 'Lower your chest to the floor, press back up, and jump or step your feet in under your hips.', 'Explode up into a jump with your arms overhead, then land softly and go again.']::text[], 'Letting the hips sag in the plank, which loads the lower back instead of the legs and core.'),
  ('Bear Crawl', ARRAY['On hands and toes with your knees hovering just off the floor, back flat.', 'Move opposite hand and foot forward together in small, controlled steps.', 'Keep your hips low and level and your head in line with your spine.']::text[], 'Pushing the hips up and rocking side to side instead of keeping the back flat.'),
  ('Hollow Body Hold', ARRAY['Lie on your back with your arms overhead and your legs straight, pressing your lower back into the floor.', 'Lift your shoulders and legs a few inches off the floor, forming a shallow banana shape.', 'Hold while breathing steadily, keeping your lower back glued to the floor.']::text[], 'Letting the lower back lift off the floor, which means the legs are too low for your core strength.'),
  ('V-Up', ARRAY['Lie on your back with your arms overhead and your legs straight.', 'Lift your legs and torso at the same time, reaching your hands toward your toes.', 'Lower both back down slowly with control, without letting your back arch.']::text[], 'Swinging with momentum so the hip flexors do the work instead of the abs.'),
  ('Pistol Squat', ARRAY['Stand on one leg with the other leg extended in front, arms forward for balance.', 'Sit back and down on the standing leg as low as you can control, keeping the heel flat.', 'Drive through the heel to stand, keeping the knee tracking over the toes.']::text[], 'Rolling onto the toes or collapsing the knee inward at the bottom.'),
  ('Dumbbell Lunge', ARRAY['Hold a dumbbell in each hand at your sides and stand tall with feet hip-width apart.', 'Step forward and lower until both knees are bent about 90 degrees, torso upright.', 'Push through the front foot to return, then switch legs.']::text[], 'Letting the front knee cave inward or the torso lean forward under the load.'),
  ('Dumbbell Goblet Squat', ARRAY['Hold one dumbbell upright against your chest with both hands, elbows pointing down.', 'Sit your hips back and down between your knees until your thighs are at least parallel.', 'Drive through your whole foot to stand, keeping your chest tall.']::text[], 'Letting the dumbbell pull your chest forward so the lower back rounds.'),
  ('Dumbbell Romanian Deadlift', ARRAY['Stand tall holding a dumbbell in each hand in front of your thighs, knees slightly bent.', 'Push your hips back and slide the dumbbells down your legs with a flat back until you feel a hamstring stretch.', 'Drive your hips forward to stand, squeezing your glutes at the top.']::text[], 'Rounding the lower back or bending the knees too much so it turns into a squat.'),
  ('Dumbbell Shoulder Press', ARRAY['Hold the dumbbells at shoulder height with your palms facing forward and your core braced.', 'Press them straight overhead until your arms are almost straight, close to your ears.', 'Lower back to shoulder height under control.']::text[], 'Arching the lower back to push the weight up instead of keeping your ribs down.'),
  ('Dumbbell Bicep Curl', ARRAY['Stand tall with a dumbbell in each hand, palms forward, elbows pinned to your sides.', 'Curl the weights up toward your shoulders without moving your upper arms.', 'Lower slowly until your arms are fully straight.']::text[], 'Swinging the torso to heave the weight up, which takes the work off the biceps.'),
  ('Dumbbell Tricep Extension', ARRAY['Hold one dumbbell with both hands overhead, arms straight and elbows close to your ears.', 'Bend your elbows to lower the dumbbell behind your head, keeping your upper arms still.', 'Straighten your arms back to the top, squeezing your triceps.']::text[], 'Letting the elbows flare out to the sides, which shifts the load and strains the elbows.'),
  ('Dumbbell Bent-Over Row', ARRAY['Hinge at the hips with a flat back and a dumbbell in each hand, arms hanging straight down.', 'Pull the dumbbells toward your hips by driving your elbows back and squeezing your shoulder blades.', 'Lower under control until your arms are straight.']::text[], 'Standing up as you pull, using body momentum instead of the back muscles.'),
  ('Dumbbell Chest Press', ARRAY['Lie on a bench with a dumbbell in each hand over your chest, feet flat and shoulder blades pinched.', 'Lower the dumbbells to the sides of your chest with elbows about 45 degrees from your body.', 'Press them back up until your arms are straight above your chest.']::text[], 'Flaring the elbows straight out to the sides, which stresses the shoulders.'),
  ('Dumbbell Step-Up', ARRAY['Hold a dumbbell in each hand and stand facing a sturdy box with one foot fully on top.', 'Drive through the top foot to stand up tall without pushing off the back foot.', 'Lower slowly under control, then repeat before switching legs.']::text[], 'Choosing a box so high that the hips twist and the torso leans to compensate.'),
  ('Resistance Band Row', ARRAY['Anchor the band at chest height, hold the ends and step back until there is tension, arms straight.', 'Pull the band toward your ribs by driving your elbows back and squeezing your shoulder blades.', 'Return slowly to straight arms without letting the band snap you forward.']::text[], 'Shrugging the shoulders up toward the ears instead of pulling them down and back.'),
  ('Resistance Band Squat', ARRAY['Stand on the band with feet shoulder-width apart and hold the ends at your shoulders.', 'Sit your hips back and down until your thighs are at least parallel.', 'Drive through your feet to stand against the band''s pull.']::text[], 'Letting the knees collapse inward as the band tension rises on the way up.'),
  ('Kettlebell Swing', ARRAY['Stand with feet a little wider than shoulder-width, kettlebell on the floor in front of you, and hinge to grip it.', 'Hike the bell back between your legs, then snap your hips forward to swing it to chest height.', 'Let it fall back and hinge again, keeping your back flat and the power in your hips.']::text[], 'Lifting the bell with the arms and squatting instead of snapping the hips.'),
  ('Renegade Row', ARRAY['Start in a high plank with your hands on two dumbbells and your feet wide for balance.', 'Row one dumbbell to your ribs while keeping your hips square to the floor.', 'Lower it under control and repeat on the other side.']::text[], 'Twisting the hips open as you row, which wastes the anti-rotation work for the core.'),
  ('Barbell Back Squat', ARRAY['Bar across your upper back, feet shoulder-width apart, chest up and core braced.', 'Sit back and down until your thighs are at least parallel, knees tracking over your toes.', 'Drive through your whole foot to stand, keeping your chest up.']::text[], 'Letting the hips shoot up first so the lower back rounds and the torso falls forward.'),
  ('Barbell Front Squat', ARRAY['Bar rests on your front shoulders with elbows high, feet shoulder-width apart.', 'Sit straight down until your thighs are at least parallel, keeping your elbows up.', 'Drive up through your feet, keeping your torso as upright as you can.']::text[], 'Letting the elbows drop, which rolls the bar forward and rounds the upper back.'),
  ('Bench Press', ARRAY['Eyes under the bar, feet flat, shoulder blades pinched together and down.', 'Lower the bar to your mid-chest with elbows about 45 degrees from your body.', 'Press up and slightly back over your shoulders until your arms are straight.']::text[], 'Bouncing the bar off the chest or lifting the hips off the bench.'),
  ('Incline Bench Press', ARRAY['Lie on an incline bench with your feet flat, shoulder blades pinched and the bar over your upper chest.', 'Lower the bar to your upper chest with elbows about 45 degrees from your body.', 'Press up until your arms are straight over your shoulders.']::text[], 'Setting the bench too steep so the shoulders take over from the upper chest.'),
  ('Deadlift', ARRAY['Bar over mid-foot, hands just outside your legs, back flat and chest up, shoulders over the bar.', 'Push the floor away and drag the bar up your legs, keeping it close to your body.', 'Stand tall with hips and knees locked, then lower the bar by sending your hips back.']::text[], 'Rounding the lower back or jerking the bar off the floor instead of pulling the slack out first.'),
  ('Romanian Deadlift', ARRAY['Stand holding the bar at your thighs with a slight knee bend and a flat back.', 'Push your hips straight back, sliding the bar down your legs until you feel a deep hamstring stretch.', 'Drive your hips forward to stand tall, squeezing your glutes.']::text[], 'Letting the bar drift away from the legs, which loads the lower back.'),
  ('Overhead Press', ARRAY['Grip the bar just outside your shoulders and hold it at your collarbone, elbows slightly in front.', 'Press the bar straight up, moving your head back and then through as the bar passes your forehead.', 'Lock out overhead with the bar over your mid-foot, then lower under control.']::text[], 'Leaning back and turning it into an incline press instead of squeezing the glutes and bracing the core.'),
  ('Bent-Over Row', ARRAY['Hinge at the hips with a flat back, bar hanging at arm''s length below your shoulders.', 'Pull the bar to your lower ribs by driving your elbows back and squeezing your shoulder blades.', 'Lower under control without letting your torso rise.']::text[], 'Standing up a little with each rep so momentum does the pulling.'),
  ('Lat Pulldown', ARRAY['Sit with your thighs under the pad, grip the bar just wider than your shoulders and lean back slightly.', 'Pull the bar to your upper chest by driving your elbows down toward your sides.', 'Let the bar rise under control until your arms are fully stretched.']::text[], 'Leaning far back and yanking the bar down, which turns the pulldown into a row.'),
  ('Cable Row', ARRAY['Sit tall with your knees slightly bent, chest up and arms reaching for the handle.', 'Pull the handle to your lower ribs, driving your elbows back and squeezing your shoulder blades.', 'Return slowly until your arms are straight without rounding your back.']::text[], 'Rocking the torso back and forth to move the weight instead of keeping it still.'),
  ('Leg Press', ARRAY['Sit with your back flat against the pad and your feet shoulder-width apart in the middle of the platform.', 'Lower the platform until your knees are bent about 90 degrees without your hips rolling up.', 'Press through your whole foot until your legs are almost straight, without locking your knees.']::text[], 'Going so deep that the lower back lifts off the pad and the pelvis tucks under.'),
  ('Leg Curl Machine', ARRAY['Set the pad just above your heels, lying or sitting snugly in the machine.', 'Curl your heels toward your glutes by squeezing your hamstrings.', 'Lower slowly until your legs are almost straight.']::text[], 'Lifting the hips off the seat to swing the weight up.'),
  ('Leg Extension Machine', ARRAY['Sit with your back against the pad and the roller just above your ankles.', 'Extend your legs until they are straight and squeeze your quads at the top.', 'Lower slowly under control rather than dropping the weight.']::text[], 'Kicking the weight up with momentum instead of a smooth, controlled lift.'),
  ('Seated Shoulder Press Machine', ARRAY['Adjust the seat so the handles start at about shoulder height, back flat against the pad.', 'Press the handles overhead until your arms are almost straight.', 'Lower slowly back to shoulder height without letting the weight stack crash.']::text[], 'Setting the seat too low or high and pressing with the elbows behind the body.'),
  ('Sun Salutation Flow', ARRAY['Stand tall, then inhale and sweep your arms overhead, exhale and fold forward from the hips.', 'Step or jump back to a plank, lower down, and press into upward dog or cobra.', 'Lift into downward dog, hold a few breaths, then step forward and rise to standing.']::text[], 'Rushing between poses and holding the breath instead of linking each move to an inhale or exhale.'),
  ('Downward Dog Flow', ARRAY['From hands and knees, tuck your toes and lift your hips up and back into an upside-down V.', 'Press your hands into the floor, lengthen your spine, and let your heels reach toward the ground.', 'Move gently through the flow by bending one knee at a time, breathing steadily.']::text[], 'Rounding the back to straighten the legs instead of bending the knees to keep the spine long.'),
  ('Warrior Sequence', ARRAY['Step one foot back wide, turn the back foot slightly in and bend the front knee over your ankle.', 'Raise your arms overhead or out to the sides, keeping your torso upright and hips facing the same way.', 'Hold for several breaths, then flow through to the next warrior and switch sides.']::text[], 'Letting the front knee collapse inward or drift past the toes.'),
  ('Child''s Pose Rest', ARRAY['Kneel with your big toes together and your knees wide apart.', 'Sit your hips back toward your heels and fold your torso forward between your knees.', 'Rest your forehead on the floor with your arms extended or by your sides, and breathe slowly.']::text[], 'Forcing the hips down when they will not reach, instead of putting a cushion under them.'),
  ('Pigeon Pose Hold', ARRAY['From downward dog, bring one knee toward your wrist and lay the shin across the mat.', 'Slide the back leg straight behind you and square your hips to the front.', 'Fold forward over the front leg and hold, breathing slowly, then switch sides.']::text[], 'Letting the hips tilt to one side and twisting the front knee instead of supporting the hip with a block.'),
  ('Cobra Pose', ARRAY['Lie face down with your hands under your shoulders and your elbows tucked in.', 'Press gently through your hands to lift your chest, keeping your lower body on the floor.', 'Keep your shoulders relaxed and gaze forward, then lower with control.']::text[], 'Pushing up with the arms until they lock, which dumps the weight into the lower back.'),
  ('Cat-Cow Yoga Flow', ARRAY['Start on hands and knees with your hands under your shoulders and knees under your hips.', 'Inhale as you drop your belly and lift your chest, then exhale as you round your spine to the ceiling.', 'Flow with your breath, moving smoothly through the whole spine.']::text[], 'Moving quickly without matching your breath, which loses the point of the flow.'),
  ('Tree Pose', ARRAY['Stand tall, shift your weight onto one leg and place the sole of the other foot on your calf or inner thigh.', 'Press the foot and leg into each other and bring your hands together at your chest or overhead.', 'Fix your gaze on a still point and hold for several breaths, then switch sides.']::text[], 'Resting the foot directly on the side of the knee, which stresses the joint.'),
  ('Triangle Pose', ARRAY['Stand with your feet wide, turn the front foot out and keep your torso long.', 'Reach forward and then hinge sideways over the front leg, resting your hand on your shin or a block.', 'Open your chest and reach the top arm up, holding for several breaths before switching sides.']::text[], 'Collapsing the chest forward instead of keeping both sides of the torso long.'),
  ('Chair Pose', ARRAY['Stand with your feet together or hip-width apart and your arms overhead.', 'Bend your knees and sit your hips back as if sitting in a chair.', 'Keep your chest lifted and weight in your heels, and hold for several breaths.']::text[], 'Letting the knees drift past the toes and the lower back arch.'),
  ('Bridge Pose', ARRAY['Lie on your back with your knees bent, feet flat and hip-width apart.', 'Press through your feet to lift your hips, rolling the spine up off the floor.', 'Keep your thighs parallel, open your chest and hold for several breaths.']::text[], 'Letting the knees splay out or pushing the hips so high that the neck gets compressed.'),
  ('Camel Pose', ARRAY['Kneel with your knees hip-width apart and your hands on your lower back.', 'Lift your chest and lean back, reaching your hands for your heels if you can.', 'Keep your hips over your knees and your neck relaxed, then come up slowly.']::text[], 'Dropping the head back and pushing the hips behind the knees, which crunches the lower back.'),
  ('Seated Twist', ARRAY['Sit tall with your legs crossed or extended and one hand behind you.', 'Turn your torso toward the back hand, using the other hand on your knee for gentle leverage.', 'Lengthen the spine on each inhale and twist a bit further on each exhale, then switch sides.']::text[], 'Cranking the spine with the arms instead of twisting from the middle of the back.'),
  ('Eagle Pose', ARRAY['Stand on one leg, wrap the other leg around it, and bend your standing knee slightly.', 'Wrap your arms around each other and lift your elbows to shoulder height.', 'Sit down a little deeper, hold steadily, then unwind and switch sides.']::text[], 'Holding the breath and gripping tightly, which makes balance harder.'),
  ('Half Moon Pose', ARRAY['From triangle, bend your front knee and step your back foot in slightly.', 'Place your front hand on the floor or a block and lift the back leg until it is level with your hip.', 'Open your chest toward the side, reach the top arm up and hold for several breaths.']::text[], 'Letting the lifted hip roll forward instead of stacking the hips.'),
  ('Crow Pose', ARRAY['Squat with your hands flat on the floor, shoulder-width apart, and bend your elbows.', 'Rest your knees on the backs of your upper arms and lean forward, shifting your weight into your hands.', 'Lift one foot and then the other, hold briefly, and lower down with control.']::text[], 'Looking down at your feet and tipping forward onto the face.'),
  ('Boat Pose', ARRAY['Sit with your knees bent and your feet on the floor, leaning back slightly with a long spine.', 'Lift your feet until your shins are parallel to the floor and reach your arms forward.', 'Hold for several breaths, then extend the legs straight if you can keep your spine long.']::text[], 'Rounding the lower back and collapsing the chest to lift the legs higher.'),
  ('Fish Pose', ARRAY['Lie on your back with your legs together and your hands under your hips.', 'Press your elbows into the floor and lift your chest, arching your upper back.', 'Lower the crown of your head gently to the floor, keeping most of the weight on the elbows, and breathe.']::text[], 'Dumping the weight onto the head and neck instead of lifting through the chest.'),
  ('Locust Pose', ARRAY['Lie face down with your arms by your sides, palms up, and your forehead on the floor.', 'Lift your head, chest, arms and legs off the floor together.', 'Hold for several breaths, keeping your neck in line, then lower.']::text[], 'Pushing the legs together and overarching, which squeezes the lower back.'),
  ('Bow Pose', ARRAY['Lie face down, bend your knees and reach back to hold your ankles.', 'Kick your feet into your hands and lift your chest and thighs off the floor.', 'Hold for a few breaths, then lower with control.']::text[], 'Pulling hard with the arms instead of kicking the feet back to create the lift.'),
  ('Extended Side Angle', ARRAY['Step into a wide lunge with your front knee bent over your ankle and your back leg straight.', 'Rest your front forearm on your thigh or your hand on the floor or a block.', 'Reach your top arm overhead along your ear and hold for several breaths.']::text[], 'Letting the front knee fall inward or putting weight onto the lower hand.'),
  ('Reverse Warrior', ARRAY['From warrior II, rest your back hand on your back leg.', 'Reach your front arm overhead and arch gently back, keeping the front knee bent.', 'Hold for several breaths, then return to warrior II.']::text[], 'Leaning on the back leg and letting the front knee collapse in.'),
  ('Low Lunge Flow', ARRAY['Step one foot forward between your hands and lower the back knee to the floor.', 'Lift your torso and reach your arms overhead as you sink your hips forward.', 'Hold for several breaths, then flow back to downward dog and switch sides.']::text[], 'Letting the front knee drift past the toes instead of stacking it over the ankle.'),
  ('High Lunge Flow', ARRAY['Step one foot forward between your hands with the back knee lifted and the leg strong.', 'Rise up, reaching your arms overhead and sinking your hips lower.', 'Hold for several breaths, then flow back and switch sides.']::text[], 'Arching the lower back instead of drawing the tailbone down and lifting the ribs.'),
  ('Standing Forward Fold', ARRAY['Stand with your feet hip-width apart and hinge forward from the hips.', 'Let your head and arms hang, with a soft bend in the knees.', 'Hold for several breaths, then roll up slowly one vertebra at a time.']::text[], 'Locking the knees and hanging from the lower back instead of bending the knees to relax the spine.'),
  ('Wide-Legged Forward Fold', ARRAY['Stand with your feet wide and parallel, hands on your hips.', 'Hinge forward from the hips with a long spine and place your hands on the floor or blocks.', 'Let your head hang and hold for several breaths, then rise slowly.']::text[], 'Collapsing the back to reach the floor instead of keeping the spine long.'),
  ('Plow Pose', ARRAY['Lie on your back, lift your legs over your head and lower your toes to the floor behind you.', 'Support your back with your hands or leave your arms on the floor.', 'Keep your neck relaxed and still, then roll out slowly.']::text[], 'Turning the head or loading the neck, which strains it.'),
  ('Shoulder Stand', ARRAY['Lie on your back, lift your legs overhead and place your hands on your lower back for support.', 'Straighten your legs to the ceiling, keeping your elbows close.', 'Keep your neck still and hold for several breaths, then lower slowly.']::text[], 'Looking around or letting the elbows splay out, which strains the neck.'),
  ('Happy Baby Pose', ARRAY['Lie on your back, bend your knees toward your chest and hold the outsides of your feet.', 'Open your knees wider than your torso and pull your feet toward the floor.', 'Rock gently from side to side, relaxing your lower back.']::text[], 'Lifting the tailbone off the floor and tensing the neck.'),
  ('Reclined Twist', ARRAY['Lie on your back, hug your knees to your chest and open your arms in a T shape.', 'Drop both knees to one side while keeping your shoulders on the floor.', 'Turn your head the other way and breathe slowly, then switch sides.']::text[], 'Forcing the knees down while the opposite shoulder lifts off the floor.'),
  ('Legs-Up-The-Wall', ARRAY['Sit sideways next to a wall and swing your legs up as you lie back.', 'Rest your legs against the wall and your arms by your sides, with your hips close to the wall.', 'Relax and breathe slowly for several minutes.']::text[], 'Sitting too far from the wall, which strains the hamstrings instead of letting them release.'),
  ('Corpse Pose', ARRAY['Lie on your back with your legs slightly apart and your arms a little away from your body, palms up.', 'Close your eyes and relax every muscle, letting your breath settle.', 'Stay still for several minutes, then roll gently to one side before getting up.']::text[], 'Fidgeting or staying tense, which stops the body from fully relaxing.'),
  ('Sphinx Pose', ARRAY['Lie face down with your forearms on the floor and your elbows under your shoulders.', 'Press gently into your forearms and lift your chest, keeping your hips down.', 'Relax your shoulders away from your ears and breathe slowly.']::text[], 'Shrugging the shoulders up and crunching the neck.'),
  ('Dolphin Pose', ARRAY['Start on hands and knees, then lower to your forearms with your elbows under your shoulders.', 'Tuck your toes and lift your hips up and back, straightening your legs as much as you can.', 'Press your forearms firmly into the floor and hold for several breaths.']::text[], 'Letting the shoulders sink into the floor instead of pushing the forearms down.'),
  ('Standing Split Pose', ARRAY['From a standing forward fold, shift your weight onto one leg.', 'Lift the other leg straight up behind you as high as you can control.', 'Keep your hips square and your hands on the floor or blocks, then lower and switch sides.']::text[], 'Opening the lifted hip to the side and locking the standing knee.'),
  ('Revolved Triangle Pose', ARRAY['Stand with your feet in a short stance, front foot forward and back foot turned slightly out.', 'Hinge forward and place the opposite hand outside the front foot, twisting your chest toward the front leg.', 'Reach the other arm to the ceiling and hold for several breaths, then switch sides.']::text[], 'Rounding the back and letting the hips twist out of line.'),
  ('Yoga with Block Support Flow', ARRAY['Place the blocks within reach and move through your usual poses.', 'Use the blocks under your hands or hips wherever the floor feels too far away.', 'Keep your spine long in each pose and breathe steadily.']::text[], 'Using blocks too low, so you still collapse instead of staying long.'),
  ('Restorative Yoga with Bolster', ARRAY['Arrange the bolster so your body can rest fully, such as along your spine or under your knees.', 'Lie back and let your body sink into the support, relaxing your muscles.', 'Stay in each pose for a few minutes, breathing slowly and deeply.']::text[], 'Holding tension in the shoulders and jaw, which defeats the restorative effect.'),
  ('Wall-Assisted Yoga Flow', ARRAY['Stand next to or facing a wall within arm''s reach.', 'Use your hands or back against the wall for support as you move through your poses.', 'Let the wall carry some of the load, and focus on a long, relaxed spine.']::text[], 'Leaning hard on the wall in every pose instead of using it only for balance.'),
  ('Yoga Strap Stretch Sequence', ARRAY['Hold a strap in your hands and loop it around your foot or hands as each pose needs.', 'Use the strap to extend your reach, keeping your spine long and your shoulders down.', 'Hold each stretch for several breaths, easing deeper only as comfortable.']::text[], 'Pulling hard on the strap instead of using it to reach a little further each breath.'),
  ('Hot Yoga Studio Flow', ARRAY['Arrive hydrated and bring a towel and plenty of water.', 'Move through the class poses at your own pace, keeping your breathing steady in the heat.', 'Rest in child''s pose whenever you feel lightheaded, and cool down gently afterwards.']::text[], 'Pushing deep into stretches because the heat makes you feel loose, which risks strains.'),
  ('Aerial Yoga Flow', ARRAY['Set the hammock at hip height and sit into it with the fabric supporting your hips.', 'Move slowly through the poses, letting the hammock take your weight and keeping your grip relaxed.', 'Come down gently, then rest in a supported pose before standing.']::text[], 'Rushing into inversions before getting used to the hammock''s movement.')
) AS v(name, form_steps, common_mistake)
WHERE e.name = v.name;
